package io.xeros.solo;
import io.xeros.*;import io.xeros.model.definitions.*;import io.xeros.model.entity.npc.drops.*;import io.xeros.content.teleportation.inter.*;import com.google.gson.*;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;
public final class LootInventory69Check {
 @SuppressWarnings("unchecked")public static void main(String[]a)throws Exception{Thread.currentThread().setName("GameThread");Server.startServerless();Field f=Server.getDropManager().getClass().getDeclaredField("groups");f.setAccessible(true);List<Map<String,Object>> groups=new ArrayList<>();int unknown=0;for(TableGroup g:((Map<List<Integer>,TableGroup>)f.get(Server.getDropManager())).values()){Map<String,Object> row=new LinkedHashMap<>();row.put("npc_ids",g.getNpcIds());List<String> names=new ArrayList<>();for(int id:g.getNpcIds())names.add(NpcDef.forId(id).getName());row.put("npc_names",names);List<Object> tables=new ArrayList<>();for(Table t:g){Map<String,Object> tr=new LinkedHashMap<>();tr.put("policy",t.getPolicy().toString());tr.put("accessibility",t.getAccessibility());List<Object> drops=new ArrayList<>();for(Drop d:t){Map<String,Object> dr=new LinkedHashMap<>();dr.put("id",d.getItemId());String name=ItemDef.forId(d.getItemId()).getName();dr.put("name",name);dr.put("min",d.getMinimumAmount());dr.put("max",d.getMaximumAmount());dr.put("known_definition",name!=null&&!name.toLowerCase().contains("unknown"));if(name==null||name.toLowerCase().contains("unknown"))unknown++;drops.add(dr);}tr.put("drops",drops);tables.add(tr);}row.put("tables",tables);groups.add(row);}List<String> routes=new ArrayList<>();for(TeleportButton b:TeleportInterfaceConstants.TELEPORT_CONTAINER_LIST.get(1).getButtonList())routes.add(b.getName());Map<String,Object> report=new LinkedHashMap<>();report.put("scope","Runtime native drop tables, including legacy/custom content; a listed table is not gameplay certification.");report.put("boss_menu",routes);report.put("groups",groups);report.put("unknown_definition_entries",unknown);Files.writeString(Path.of("D:/Games/OSRS/relatorios/combate-v69/inventario-bosses-drops.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));System.out.println("LOOT_INVENTORY68_PASS GROUPS="+groups.size()+" UNKNOWN_LEGACY_ENTRIES="+unknown);System.exit(0);}
}
